UPDATE pm_timesheet SET voucher_id = #{voucherId}, update_time = NOW()
WHERE project_id = #{projectId} AND status = 'APPROVED' AND voucher_id IS NULL
  AND work_date >= #{begin} AND work_date <= #{end}

UPDATE pm_cost SET voucher_id = #{voucherId}, update_time = NOW()
WHERE project_id = #{projectId} AND source = 'MANUAL' AND status = 'APPROVED' AND voucher_id IS NULL
  AND cost_date >= #{begin} AND cost_date <= #{end}
